import os
import secrets
import hashlib
import base64
from urllib.parse import urlencode

from flask import Flask, redirect, request, session, jsonify
from authlib.integrations.flask_client import OAuth

app = Flask(__name__)
app.secret_key = os.environ["FLASK_SECRET_KEY"]

AUTH0_DOMAIN = os.environ["AUTH0_DOMAIN"]
AUTH0_CLIENT_ID = os.environ["AUTH0_CLIENT_ID"]
AUTH0_CLIENT_SECRET = os.environ["AUTH0_CLIENT_SECRET"]
AUTH0_CALLBACK_URL = os.environ["AUTH0_CALLBACK_URL"]

oauth = OAuth(app)
oauth.register(
    name="auth0",
    client_id=AUTH0_CLIENT_ID,
    client_secret=AUTH0_CLIENT_SECRET,
    server_metadata_url=f"https://{AUTH0_DOMAIN}/.well-known/openid-configuration",
    client_kwargs={"scope": "openid profile email"},
)

def _base64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

def _pkce_pair():
    verifier = _base64url(secrets.token_bytes(32))
    challenge = _base64url(hashlib.sha256(verifier.encode("ascii")).digest())
    return verifier, challenge

@app.route("/login")
def login():
    verifier, challenge = _pkce_pair()
    state = secrets.token_urlsafe(24)

    session["oidc_state"] = state
    session["pkce_verifier"] = verifier

    authorization_endpoint = f"https://{AUTH0_DOMAIN}/authorize"
    params = {
        "response_type": "code",
        "client_id": AUTH0_CLIENT_ID,
        "redirect_uri": AUTH0_CALLBACK_URL,
        "scope": "openid profile email",
        "state": state,
        "code_challenge": challenge,
        "code_challenge_method": "S256",
        "audience": request.args.get("audience") or os.environ.get("AUTH0_AUDIENCE", ""),
    }
    params = {k: v for k, v in params.items() if v}
    return redirect(f"{authorization_endpoint}?{urlencode(params)}", code=302)

@app.route("/callback")
def callback():
    if request.args.get("state") != session.get("oidc_state"):
        return jsonify({"error": "invalid_state"}), 400

    token = oauth.auth0.authorize_access_token(
        code_verifier=session.get("pkce_verifier")
    )
    userinfo = token.get("userinfo")
    if not userinfo:
        userinfo = oauth.auth0.userinfo()

    session.pop("oidc_state", None)
    session.pop("pkce_verifier", None)

    return jsonify(
        {
            "access_token": token.get("access_token"),
            "id_token": token.get("id_token"),
            "token_type": token.get("token_type"),
            "userinfo": userinfo,
        }
    )

@app.route("/logout")
def logout():
    session.clear()
    params = urlencode(
        {
            "client_id": AUTH0_CLIENT_ID,
            "returnTo": request.host_url.rstrip("/"),
        }
    )
    return redirect(f"https://{AUTH0_DOMAIN}/v2/logout?{params}", code=302)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", "8000")))
